<?php declare(strict_types=1); /** @var list<array<string,mixed>> $items */ /** @var bool $canCreate */ ?>
<div class="container-fluid py-3"><h1 class="h3 mb-3"><?php echo htmlspecialchars((string)($title??''), ENT_QUOTES,'UTF-8'); ?></h1>
